const STATUS_ORDER = [
  "accepted",
  "declined",
  "tentative",
  "needsAction",
] as const;

/** A monogram is a single letter or digit. Anything else - punctuation, an
 *  emoji, whitespace-only, or null - falls back to the person glyph. That is
 *  what keeps the rendered monogram free of "@": no attendee-supplied character
 *  that is not \p{L} or \p{N} reaches the rendered text. The per-avatar title
 *  attribute was removed in RF-01, so no attendee-supplied text reaches the DOM
 *  at all - not merely no "@". */
const MONOGRAM_CHARACTER = /^[\p{L}\p{N}]$/u;

