/** Walks the full list once with a plain integer accumulator. Deliberately not
 *  .filter(...).length - that allocates an intermediate array on the grid's hot
 *  path. Do not "optimize" this into a filter. */
const countAccepted = (attendees: readonly Attendee[]): number => {
  let accepted = 0;
  for (const attendee of attendees) {
    if (attendee.responseStatus === "accepted") accepted += 1;
  }
  return accepted;
};

new_string:
/** Walks the full list once with a plain integer accumulator per status.
 *  Deliberately not a per-status .filter(...).length - that would allocate one
 *  intermediate array per status on the grid's hot path. Do not "optimize" this
 *  into filters. */
const countByStatus = (
  attendees: readonly Attendee[],
): Record<AttendeeResponseStatus, number> => {
  const counts: Record<AttendeeResponseStatus, number> = {
    accepted: 0,
    declined: 0,
    tentative: 0,
    needsAction: 0,
  };
  for (const attendee of attendees) {
    counts[attendee.responseStatus] += 1;
  }
  return counts;
};

